import{_ as l,a0 as t,w as o,s as d,ao as c,I as p,x as a,a1 as i,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"8 个用于有效地管理进程的 Linux 命令 | LCTT x X-CMD","titleTemplate":false,"description":"8 个用于有效地管理进程的 Linux 命令 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"8 个用于有效地管理进程的 Linux 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"8 个用于有效地管理进程的 Linux 命令 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180904 8 Linux commands for effective process management","title":"8 个用于有效地管理进程的 Linux 命令","tag":"201809","desc":""},"relativePath":"201809/20180904 8 Linux commands for effective process management.md","filePath":"[post].md"}'),r={name:"201809/20180904 8 Linux commands for effective process management.md"};function h(g,s,k,b,u,f){const n=t("Link");return o(),d("div",null,[s[18]||(s[18]=c(`<h1 id="_8-个用于有效地管理进程的-linux-命令" tabindex="-1">8 个用于有效地管理进程的 Linux 命令 <a class="header-anchor" href="#_8-个用于有效地管理进程的-linux-命令" aria-label="Permalink to “8 个用于有效地管理进程的 Linux 命令”">​</a></h1><blockquote><p>通过这些关键的命令来全程管理你的应用。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/command_line_prompt.png?itok=wbGiJ_yg" alt=""></p><p>一般来说，应用程序进程的生命周期有三种主要状态：启动、运行和停止。如果我们想成为称职的管理员，每个状态都可以而且应该得到认真的管理。这八个命令可用于管理进程的整个生命周期。</p><h3 id="启动进程" tabindex="-1">启动进程 <a class="header-anchor" href="#启动进程" aria-label="Permalink to “启动进程”">​</a></h3><p>启动进程的最简单方法是在命令行中键入其名称，然后按回车键。如果要启动 Nginx web 服务器，请键入 <code>nginx</code> 。也许您只是想看看其版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ nginx</span></span>
<span class="line"><span></span></span>
<span class="line"><span>alan@workstation:~$ nginx -v</span></span>
<span class="line"><span>nginx version: nginx/1.14.0</span></span></code></pre></div><h3 id="查看您的可执行路径" tabindex="-1">查看您的可执行路径 <a class="header-anchor" href="#查看您的可执行路径" aria-label="Permalink to “查看您的可执行路径”">​</a></h3><p>以上启动进程的演示是假设可执行文件位于您的可执行路径中。理解这个路径是可靠地启动和管理进程的关键。管理员通常会为他们想要的目的定制这条路径。您可以使用 <code>echo $PATH</code> 查看您的可执行路径。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ echo $PATH</span></span>
<span class="line"><span>/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin</span></span></code></pre></div><h4 id="which" tabindex="-1">WHICH <a class="header-anchor" href="#which" aria-label="Permalink to “WHICH”">​</a></h4><p>使用 <code>which</code> 命令查看可执行文件的完整路径。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ which nginx</span></span>
<span class="line"><span>/opt/nginx/bin/nginx</span></span></code></pre></div><p>我将使用流行的 web 服务器软件 Nginx 作为我的例子。假设安装了 Nginx。如果执行 <code>which nginx</code> 的命令什么也不返回，那么是找不到 Nginx 了，因为它只搜索您指定的可执行路径。有三种方法可以补救一个进程不能简单地通过名字启动的情况。首先是键入完整路径 —— 虽然，我不情愿输入全部路径，您会吗？</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ /home/alan/web/prod/nginx/sbin/nginx -v</span></span>
<span class="line"><span>nginx version: nginx/1.14.0</span></span></code></pre></div><p>第二个解决方案是将应用程序安装在可执行文件路径中的目录中。然而，这有时可能是办不到的，特别是如果您没有 root 权限。</p><p>第三个解决方案是更新您的可执行路径环境变量，包括要使用的特定应用程序的安装目录。这个解决方案是与 shell 相关的。例如，Bash 用户需要在他们的 <code>.bashrc</code> 文件中编辑 <code>PATH=</code> 行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PATH=&quot;$HOME/web/prod/nginx/sbin:$PATH&quot;</span></span></code></pre></div><p>现在，重复您的 <code>echo</code> 和 <code>which</code> 命令或者尝试检查版本。容易多了！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ echo $PATH</span></span>
<span class="line"><span>/home/alan/web/prod/nginx/sbin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin</span></span>
<span class="line"><span></span></span>
<span class="line"><span>alan@workstation:~$ which nginx</span></span>
<span class="line"><span>/home/alan/web/prod/nginx/sbin/nginx</span></span>
<span class="line"><span></span></span>
<span class="line"><span>alan@workstation:~$ nginx -v                                                </span></span>
<span class="line"><span>nginx version: nginx/1.14.0</span></span></code></pre></div><h3 id="保持进程运行" tabindex="-1">保持进程运行 <a class="header-anchor" href="#保持进程运行" aria-label="Permalink to “保持进程运行”">​</a></h3><h4 id="nohup" tabindex="-1">NOHUP <a class="header-anchor" href="#nohup" aria-label="Permalink to “NOHUP”">​</a></h4><p>注销或关闭终端时，进程可能不会继续运行。这种特殊情况可以通过在要使用 <code>nohup</code> 命令放在要运行的命令前面让进程持续运行。此外，附加一个<code>&amp;</code> 符号将会把进程发送到后台，并允许您继续使用终端。例如，假设您想运行 <code>myprogram.sh</code> 。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nohup myprogram.sh &amp;</span></span></code></pre></div><p><code>nohup</code> 会返回运行进程的 PID。接下来我会更多地谈论 PID。</p><h3 id="管理正在运行的进程" tabindex="-1">管理正在运行的进程 <a class="header-anchor" href="#管理正在运行的进程" aria-label="Permalink to “管理正在运行的进程”">​</a></h3><p>每个进程都有一个唯一的进程标识号 (PID) 。这个数字是我们用来管理每个进程的。我们还可以使用进程名称，我将在下面演示。有几个命令可以检查正在运行的进程的状态。让我们快速看看这些命令。</p><h4 id="ps" tabindex="-1">PS <a class="header-anchor" href="#ps" aria-label="Permalink to “PS”">​</a></h4><p>最常见的是 <code>ps</code> 命令。<code>ps</code> 的默认输出是当前终端中运行的进程的简单列表。如下所示，第一列包含 PID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ ps</span></span>
<span class="line"><span>PID TTY          TIME CMD</span></span>
<span class="line"><span>23989 pts/0    00:00:00 bash</span></span>
<span class="line"><span>24148 pts/0    00:00:00 ps</span></span></code></pre></div><p>我想看看我之前启动的 Nginx 进程。为此，我告诉 <code>ps</code> 给我展示每一个正在运行的进程（<code>-e</code>）和完整的列表（<code>-f</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ ps -ef</span></span>
<span class="line"><span>UID        PID  PPID  C STIME TTY          TIME CMD</span></span>
<span class="line"><span>root         1     0  0 Aug18 ?        00:00:10 /sbin/init splash</span></span>
<span class="line"><span>root         2     0  0 Aug18 ?        00:00:00 [kthreadd]</span></span>
<span class="line"><span>root         4     2  0 Aug18 ?        00:00:00 [kworker/0:0H]</span></span>
<span class="line"><span>root         6     2  0 Aug18 ?        00:00:00 [mm_percpu_wq]</span></span>
<span class="line"><span>root         7     2  0 Aug18 ?        00:00:00 [ksoftirqd/0]</span></span>
<span class="line"><span>root         8     2  0 Aug18 ?        00:00:20 [rcu_sched]</span></span>
<span class="line"><span>root         9     2  0 Aug18 ?        00:00:00 [rcu_bh]</span></span>
<span class="line"><span>root        10     2  0 Aug18 ?        00:00:00 [migration/0]</span></span>
<span class="line"><span>root        11     2  0 Aug18 ?        00:00:00 [watchdog/0]</span></span>
<span class="line"><span>root        12     2  0 Aug18 ?        00:00:00 [cpuhp/0]</span></span>
<span class="line"><span>root        13     2  0 Aug18 ?        00:00:00 [cpuhp/1]</span></span>
<span class="line"><span>root        14     2  0 Aug18 ?        00:00:00 [watchdog/1]</span></span>
<span class="line"><span>root        15     2  0 Aug18 ?        00:00:00 [migration/1]</span></span>
<span class="line"><span>root        16     2  0 Aug18 ?        00:00:00 [ksoftirqd/1]</span></span>
<span class="line"><span>alan     20506 20496  0 10:39 pts/0    00:00:00 bash</span></span>
<span class="line"><span>alan     20520  1454  0 10:39 ?        00:00:00 nginx: master process nginx</span></span>
<span class="line"><span>alan     20521 20520  0 10:39 ?        00:00:00 nginx: worker process</span></span>
<span class="line"><span>alan     20526 20506  0 10:39 pts/0    00:00:00 man ps</span></span>
<span class="line"><span>alan     20536 20526  0 10:39 pts/0    00:00:00 pager</span></span>
<span class="line"><span>alan     20564 20496  0 10:40 pts/1    00:00:00 bash</span></span></code></pre></div><p>您可以在上面 <code>ps</code> 命令的输出中看到 Nginx 进程。这个命令显示了将近 300 行，但是我在这个例子中缩短了它。可以想象，试图处理 300 行过程信息有点混乱。我们可以将这个输出输送到 <code>grep</code>，过滤一下仅显示 nginx。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ ps -ef |grep nginx</span></span>
<span class="line"><span>alan     20520  1454  0 10:39 ?        00:00:00 nginx: master process nginx</span></span>
<span class="line"><span>alan     20521 20520  0 10:39 ?        00:00:00 nginx: worker process</span></span></code></pre></div><p>确实更好了。我们可以很快看到，Nginx 有 20520 和 20521 的 PID。</p><h4 id="pgrep" tabindex="-1">PGREP <a class="header-anchor" href="#pgrep" aria-label="Permalink to “PGREP”">​</a></h4><p><code>pgrep</code> 命令更加简化单独调用 <code>grep</code> 遇到的问题。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ pgrep nginx</span></span>
<span class="line"><span>20520</span></span>
<span class="line"><span>20521</span></span></code></pre></div><p>假设您在一个托管环境中，多个用户正在运行几个不同的 Nginx 实例。您可以使用 <code>-u</code> 选项将其他人排除在输出之外。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ pgrep -u alan nginx</span></span>
<span class="line"><span>20520</span></span>
<span class="line"><span>20521</span></span></code></pre></div><h4 id="pidof" tabindex="-1">PIDOF <a class="header-anchor" href="#pidof" aria-label="Permalink to “PIDOF”">​</a></h4><p>另一个好用的是 <code>pidof</code>。此命令将检查特定二进制文件的 PID，即使另一个同名进程正在运行。为了建立一个例子，我将我的 Nginx 复制到第二个目录，并以相应的路径前缀启动。在现实生活中，这个实例可能位于不同的位置，例如由不同用户拥有的目录。如果我运行两个 Nginx 实例，则<code>pidof</code> 输出显示它们的所有进程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ ps -ef |grep nginx</span></span>
<span class="line"><span>alan     20881  1454  0 11:18 ?        00:00:00 nginx: master process ./nginx -p /home/alan/web/prod/nginxsec</span></span>
<span class="line"><span>alan     20882 20881  0 11:18 ?        00:00:00 nginx: worker process</span></span>
<span class="line"><span>alan     20895  1454  0 11:19 ?        00:00:00 nginx: master process nginx</span></span>
<span class="line"><span>alan     20896 20895  0 11:19 ?        00:00:00 nginx: worker process</span></span></code></pre></div><p>使用 <code>grep</code> 或 <code>pgrep</code> 将显示 PID 数字，但我们可能无法辨别哪个实例是哪个。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ pgrep nginx</span></span>
<span class="line"><span>20881</span></span>
<span class="line"><span>20882</span></span>
<span class="line"><span>20895</span></span>
<span class="line"><span>20896</span></span></code></pre></div><p><code>pidof</code> 命令可用于确定每个特定 Nginx 实例的 PID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ pidof /home/alan/web/prod/nginxsec/sbin/nginx</span></span>
<span class="line"><span>20882 20881</span></span>
<span class="line"><span></span></span>
<span class="line"><span>alan@workstation:~$ pidof /home/alan/web/prod/nginx/sbin/nginx</span></span>
<span class="line"><span>20896 20895</span></span></code></pre></div><h4 id="top" tabindex="-1">TOP <a class="header-anchor" href="#top" aria-label="Permalink to “TOP”">​</a></h4><p><code>top</code> 命令已经有很久的历史了，对于查看运行进程的细节和快速识别内存消耗等问题是非常有用的。其默认视图如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>top - 11:56:28 up 1 day, 13:37,  1 user,  load average: 0.09, 0.04, 0.03</span></span>
<span class="line"><span>Tasks: 292 total,   3 running, 225 sleeping,   0 stopped,   0 zombie</span></span>
<span class="line"><span>%Cpu(s):  0.1 us,  0.2 sy,  0.0 ni, 99.7 id,  0.0 wa,  0.0 hi,  0.0 si,  0.0 st</span></span>
<span class="line"><span>KiB Mem : 16387132 total, 10854648 free,  1859036 used,  3673448 buff/cache</span></span>
<span class="line"><span>KiB Swap:        0 total,        0 free,        0 used. 14176540 avail Mem</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  PID USER      PR  NI    VIRT    RES    SHR S  %CPU %MEM     TIME+ COMMAND</span></span>
<span class="line"><span>17270 alan      20   0 3930764 247288  98992 R   0.7  1.5   5:58.22 gnome-shell</span></span>
<span class="line"><span>20496 alan      20   0  816144  45416  29844 S   0.5  0.3   0:22.16 gnome-terminal-</span></span>
<span class="line"><span>21110 alan      20   0   41940   3988   3188 R   0.1  0.0   0:00.17 top</span></span>
<span class="line"><span>    1 root      20   0  225564   9416   6768 S   0.0  0.1   0:10.72 systemd</span></span>
<span class="line"><span>    2 root      20   0       0      0      0 S   0.0  0.0   0:00.01 kthreadd</span></span>
<span class="line"><span>    4 root       0 -20       0      0      0 I   0.0  0.0   0:00.00 kworker/0:0H</span></span>
<span class="line"><span>    6 root       0 -20       0      0      0 I   0.0  0.0   0:00.00 mm_percpu_wq</span></span>
<span class="line"><span>    7 root      20   0       0      0      0 S   0.0  0.0   0:00.08 ksoftirqd/0</span></span></code></pre></div><p>可以通过键入字母 <code>s</code> 和您喜欢的更新秒数来更改更新间隔。为了更容易监控我们的示例 Nginx 进程，我们可以使用 <code>-p</code> 选项并传递 PID 来调用 <code>top</code>。这个输出要干净得多。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ top -p20881 -p20882 -p20895 -p20896</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Tasks:   4 total,   0 running,   4 sleeping,   0 stopped,   0 zombie</span></span>
<span class="line"><span>%Cpu(s):  2.8 us,  1.3 sy,  0.0 ni, 95.9 id,  0.0 wa,  0.0 hi,  0.0 si,  0.0 st</span></span>
<span class="line"><span>KiB Mem : 16387132 total, 10856008 free,  1857648 used,  3673476 buff/cache</span></span>
<span class="line"><span>KiB Swap:        0 total,        0 free,        0 used. 14177928 avail Mem</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  PID USER      PR  NI    VIRT    RES    SHR S  %CPU %MEM     TIME+ COMMAND</span></span>
<span class="line"><span>20881 alan      20   0   12016    348      0 S   0.0  0.0   0:00.00 nginx</span></span>
<span class="line"><span>20882 alan      20   0   12460   1644    932 S   0.0  0.0   0:00.00 nginx</span></span>
<span class="line"><span>20895 alan      20   0   12016    352      0 S   0.0  0.0   0:00.00 nginx</span></span>
<span class="line"><span>20896 alan      20   0   12460   1628    912 S   0.0  0.0   0:00.00 nginx</span></span></code></pre></div><p>在管理进程，特别是终止进程时，正确确定 PID 是非常重要。此外，如果以这种方式使用 <code>top</code>，每当这些进程中的一个停止或一个新进程开始时，<code>top</code> 都需要被告知有新的进程。</p><h3 id="终止进程" tabindex="-1">终止进程 <a class="header-anchor" href="#终止进程" aria-label="Permalink to “终止进程”">​</a></h3><h4 id="kill" tabindex="-1">KILL <a class="header-anchor" href="#kill" aria-label="Permalink to “KILL”">​</a></h4><p>有趣的是，没有 <code>stop</code> 命令。在 Linux 中，有 <code>kill</code> 命令。<code>kill</code> 用于向进程发送信号。最常用的信号是“终止”（<code>SIGTERM</code>）或“杀死”（<code>SIGKILL</code>）。然而，还有更多。下面是一些例子。完整的列表可以用 <code>kill -L</code> 显示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> 1) SIGHUP       2) SIGINT       3) SIGQUIT      4) SIGILL       5) SIGTRAP</span></span>
<span class="line"><span> 6) SIGABRT      7) SIGBUS       8) SIGFPE       9) SIGKILL     10) SIGUSR1</span></span>
<span class="line"><span>11) SIGSEGV     12) SIGUSR2     13) SIGPIPE     14) SIGALRM     15) SIGTERM</span></span></code></pre></div><p>注意第 9 号信号是 <code>SIGKILL</code>，通常，我们会发出比如 <code>kill -9 20896</code> 这样的命令。默认信号是 15，这是 <code>SIGTERM</code>。请记住，许多应用程序都有自己的停止方法。Nginx 使用 <code>-s</code> 选项传递信号，如 <code>stop</code> 或 <code>reload</code>。通常，我更喜欢使用应用程序的特定方法来停止操作。然而，我将演示用 <code>kill</code> 命令来停止 Nginx 进程 20896，然后用 <code>pgrep</code> 确认它已经停止。PID 20896 就不再出现。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ kill -9 20896</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>alan@workstation:~$ pgrep nginx</span></span>
<span class="line"><span>20881</span></span>
<span class="line"><span>20882</span></span>
<span class="line"><span>20895</span></span>
<span class="line"><span>22123</span></span></code></pre></div><h4 id="pkill" tabindex="-1">PKILL <a class="header-anchor" href="#pkill" aria-label="Permalink to “PKILL”">​</a></h4><p>命令 <code>pkill</code> 类似于 <code>pgrep</code>，因为它可以按名称搜索。这意味着在使用 <code>pkill</code> 时必须非常小心。在我的 Nginx 示例中，如果我只想杀死一个 Nginx 实例，我可能不会选择使用它。我可以将 Nginx 选项 <code>-s stop</code> 传递给特定的实例来消除它，或者我需要使用 <code>grep</code> 来过滤整个 <code>ps</code> 输出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/home/alan/web/prod/nginx/sbin/nginx -s stop</span></span>
<span class="line"><span>/home/alan/web/prod/nginxsec/sbin/nginx -s stop</span></span></code></pre></div><p>如果我想使用 <code>pkill</code>，我可以包括 <code>-f</code> 选项，让 <code>pkill</code> 过滤整个命令行参数。这当然也适用于 <code>pgrep</code>。所以，在执行 <code>pkill -f</code> 之前，首先我可以用 <code>pgrep -a</code> 确认一下。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ pgrep -a nginx</span></span>
<span class="line"><span>20881 nginx: master process ./nginx -p /home/alan/web/prod/nginxsec</span></span>
<span class="line"><span>20882 nginx: worker process</span></span>
<span class="line"><span>20895 nginx: master process nginx</span></span>
<span class="line"><span>20896 nginx: worker process</span></span></code></pre></div><p>我也可以用 <code>pgrep -f</code> 缩小我的结果。<code>pkill</code> 使用相同参数会停止该进程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation:~$ pgrep -f nginxsec</span></span>
<span class="line"><span>20881</span></span>
<span class="line"><span>                                           </span></span>
<span class="line"><span>alan@workstation:~$ pkill -f nginxsec</span></span></code></pre></div><p><code>pgrep</code>（尤其是 <code>pkill</code>）要记住的关键点是，您必须始终确保搜索结果准确性，这样您就不会无意中影响到错误的进程。</p>`,67)),p("p",null,[s[1]||(s[1]=a("大多数这些命令都有许多命令行选项，所以我总是建议阅读每一个命令的 ",-1)),i(n,{href:"https://www.kernel.org/doc/man-pages/"},{default:e(()=>[...s[0]||(s[0]=[a("man 手册页",-1)])]),_:1}),s[2]||(s[2]=a("。虽然大多数这些命令都存在于 Linux、Solaris 和 BSD 等平台上，但也有一些不同之处。在命令行工作或编写脚本时，始终测试并随时准备根据需要进行更正。",-1))]),s[19]||(s[19]=p("hr",null,null,-1)),p("p",null,[s[4]||(s[4]=a("via: ",-1)),i(n,{href:"https://opensource.com/article/18/9/linux-commands-process-management"},{default:e(()=>[...s[3]||(s[3]=[a("https://opensource.com/article/18/9/linux-commands-process-management",-1)])]),_:1})]),p("p",null,[s[9]||(s[9]=a("作者：",-1)),i(n,{href:"https://opensource.com/users/alanfdoss"},{default:e(()=>[...s[5]||(s[5]=[a("Alan Formy-Duval",-1)])]),_:1}),s[10]||(s[10]=a(" 选题：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 译者：",-1)),i(n,{href:"https://github.com/heguangzhi"},{default:e(()=>[...s[7]||(s[7]=[a("heguangzhi",-1)])]),_:1}),s[12]||(s[12]=a(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[15]||(s[15]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...s[14]||(s[14]=[a("Linux中国",-1)])]),_:1}),s[17]||(s[17]=a(" 荣誉推出",-1))])])}const C=l(r,[["render",h]]);export{y as __pageData,C as default};
